mapper.select:
/* 프로그램 사용 이력관리 (7022) */
/* AdminLogProgramMapper.selectListTotCnt */
SELECT COUNT(*) totcnt
FROM CSPD811TH A
WHERE 1=1

/* 프로그램 사용 이력관리 (7022) */
/* AdminLogProgramMapper.selectCheckActionCodeUsingYN */
SELECT AI_INPT_CMN_USG_YN FROM CSPD112TI
 WHERE AI_INPT_GRP_CD = '701'
   AND AI_INPT_CMN_CD = #{value}

mapper.insert:
	/* 프로그램 사용 이력관리 (7022) */
	/* AdminLogProgramMapper.insert */
	INSERT INTO CSPD811TH (
		AI_INPT_PGM_USG_HST_NO
		, AI_INPT_CNCT_USER_NO
		, AI_INPT_CNCT_IPAD
		, AI_INPT_CNCT_MCHR_NM
		, AI_INPT_CNCT_SCRN_NO
     	, AI_INPT_CNCT_FLD_CD 
	    , AI_INPT_CNCT_ACTI_CD 
		, AI_INPT_CNCT_PARM_TXT
		, TRN_LOG_SRNO
		, LST_DB_CHG_ID
		, LST_DB_CHG_DTM
	) VALUES (

		(SELECT SUBSTR(TO_CHAR(SYSTIMESTAMP, 'YYYYMMDDHH24MISSFF6'), 1, 17) || LPAD(ROUND(DBMS_RANDOM.VALUE(1, 999)), 3, 0) FROM DUAL)
		, #{aiInptCnctUserNo}
		, #{aiInptCnctIpad}
		, SUBSTRB(#{aiInptCnctMchrNm},1,199)
		, #{aiInptCnctScrnNo}
		, #{aiInptCnctFldCd} 
		, #{aiInptCnctActiCd} 
		, SUBSTRB(#{aiInptCnctParmTxt},1,999)
		, #{trnLogSrno}
		, #{lstDbChgId}
		, 
	)
